/**
 * The service worker.
 *
 * Three jobs: make the portal installable to a home screen, make it open
 * instantly rather than refetching the shell, and receive push — the last of
 * which is the only way anything here can reach you with the app closed.
 *
 * It does NOT make the app work offline. Reading and writing data still needs
 * Supabase, and a write queue that survives being offline is a different and
 * much larger project. Better to be honest about that than to ship a shell
 * that opens to an empty room and looks broken.
 *
 * Hand-written rather than generated by vite-plugin-pwa: the whole thing is
 * sixty lines, this project adds no dependency it can avoid, and a generated
 * worker is the last place anyone wants a surprise on a rolldown upgrade.
 *
 * Cache invalidation is mostly handled for us. Vite fingerprints every built
 * asset (`index-BAdIwwjG.js`), so a new build asks for new filenames and the
 * old entries simply stop being requested; CACHE is bumped only when the
 * logic in this file changes, and activate then clears anything older.
 *
 * This file itself is served no-cache (see the headers block in vercel.json —
 * which takes no comments of its own, JSON being JSON and Vercel rejecting
 * unknown keys). Without that a fix to this worker could sit unseen for as
 * long as the browser's default lifetime, since everything it caches is
 * fingerprinted but the worker is not.
 */
const CACHE = 'orra-v1';

self.addEventListener('install', (event) => {
  // The new worker should take over on the next navigation, not the next
  // browser restart — otherwise a fix can sit unused for days.
  self.skipWaiting();
  event.waitUntil(caches.open(CACHE));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((name) => name !== CACHE).map((name) => caches.delete(name)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  // Same-origin GETs only. Supabase, Google and the font CDNs must never be
  // touched: caching an API response here would serve stale data with no way
  // to tell, and caching an authenticated one would be worse.
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Navigations: network first, so a deploy is picked up immediately, with
  // the cached shell as the fallback when the network is slow or gone.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(request);
          const cache = await caches.open(CACHE);
          cache.put('/index.html', fresh.clone());
          return fresh;
        } catch {
          const cached = await caches.match('/index.html');
          return cached ?? Response.error();
        }
      })(),
    );
    return;
  }

  // Fingerprinted build output: cache first. The filename changes whenever
  // the contents do, so a hit is always correct.
  if (url.pathname.startsWith('/assets/') || url.pathname.startsWith('/icons/')) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request);
        if (cached) return cached;
        const fresh = await fetch(request);
        if (fresh.ok) {
          const cache = await caches.open(CACHE);
          cache.put(request, fresh.clone());
        }
        return fresh;
      })(),
    );
  }
});

/* ── Push ──────────────────────────────────────────────────────────────────
   This is the part that works with the app closed. The browser wakes this
   worker, hands it the payload the edge function sealed, and it shows a
   notification — no page, no tab, no React. */

self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    // A payload that will not parse still deserves to surface: silence here
    // reads as "push is broken" from the outside.
    data = { title: 'ORRA', body: event.data ? event.data.text() : '' };
  }
  const title = data.title || 'ORRA';
  event.waitUntil(
    self.registration.showNotification(title, {
      body: data.body || '',
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      // Same tag replaces rather than stacks, so five due-date pushes in a
      // morning are one line on the lock screen instead of five.
      tag: data.tag || 'orra',
      renotify: Boolean(data.renotify),
      data: { url: data.url || '/' },
      timestamp: Date.now(),
    }),
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || '/';
  event.waitUntil(
    (async () => {
      const all = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      // Reuse a window that is already open rather than stacking another copy
      // of the app — then send it where the notification pointed.
      for (const client of all) {
        if (new URL(client.url).origin === self.location.origin) {
          await client.focus();
          if ('navigate' in client) await client.navigate(target);
          return;
        }
      }
      await self.clients.openWindow(target);
    })(),
  );
});

